269	     * The owner's membership points, derived at read time from stored fields. Starts at 0; add 2 when
270	     * an email is present; add 1 when {@link #getNamesakeCount() namesakeCount} is 0; add 2 for a
271	     * household of 3 or more ({@link #getHouseholdSize() householdSize}); add 3 when tenure (days since
272	     * {@link #getRegistrationDate() registrationDate}) exceeds 365. A newly created owner has zero
273	     * tenure, so a new owner can score at most 5 points.
274	     */
275	    @Transient
276	    public Integer getMembershipPoints() {
277	        int points = 0;
278	        boolean hasEmail = this.email != null && !this.email.isBlank();
279	        if (hasEmail) {
280	            points += 2;
281	        }
282	        if (this.namesakeCount != null && this.namesakeCount == 0) {
283	            points += 1;
284	        }
285	        if (this.householdSize != null && this.householdSize >= 3) {
286	            points += 2;
287	        }
288	        if (this.registrationDate != null
289	                && java.time.temporal.ChronoUnit.DAYS.between(this.registrationDate, LocalDate.now()) > 365) {
290	            points += 3;
291	        }
292	        return points;
293	    }
294	
295	    /**
296	     * The owner's membership level, a number from 1 to 4 derived at read time by banding
297	     * {@link #getMembershipPoints() membershipPoints}: 1 (0-1 points), 2 (2-3), 3 (4-5), 4 (6 or more).
298	     * Because a new owner scores at most 5 points, only tenure (+3) can reach level 4.
299	     */
300	    @Transient
301	    public Integer getMembershipLevel() {
302	        int points = getMembershipPoints();
303	        if (points <= 1) {
304	            return 1;
305	        }
306	        if (points <= 3) {
307	            return 2;
308	        }
309	        if (points <= 5) {
310	            return 3;
311	        }
312	        return 4;
313	    }
314	
315	    /**
316	     * A single Luhn check digit (0-9) computed at read time over the digits contained in the
317	     * {@link #getCustomerCode() customerCode} (non-digit characters such as the '-' separators are
318	     * ignored). {@code null} when the owner has no customerCode.
319	     */
320	    @Transient
321	    public Integer getCheckDigit() {
322	        if (this.customerCode == null) {
323	            return null;
324	        }
325	        int sum = 0;
326	        boolean dbl = true;
327	        for (int i = this.customerCode.length() - 1; i >= 0; i--) {
328	            char c = this.customerCode.charAt(i);
329	            if (c < '0' || c > '9') {
330	                continue;
331	            }
332	            int d = c - '0';
